[CmdletBinding()]
param()

$ErrorActionPreference = 'Stop'
$designRoot = Split-Path -Parent $PSCommandPath

. (Join-Path $designRoot 'ide_controls.ps1')
. (Join-Path $designRoot 'ide_chrome.ps1')
$ideComponents = Import-IdeSvgComponents (Join-Path $designRoot 'components')
$profilesRoot = Join-Path (Split-Path -Parent $designRoot) '../profiles'
$targetPresets = @{}
Get-ChildItem -LiteralPath $profilesRoot -File -Filter '*.json' | Where-Object Name -ne 'profile.schema.json' | ForEach-Object {
    $preset = Get-Content -LiteralPath $_.FullName -Raw | ConvertFrom-Json -AsHashtable
    if ($targetPresets.ContainsKey($preset.id)) { throw "Duplicate preset ID '$($preset.id)'." }
    $targetPresets[$preset.id] = $preset
}

